% mathsmap-diagram-colours {"version":1,"kind":"graph","base":[],"semantic":[{"name":"seriesBlue","hex":"268CFF","reason":"y=2^x series"},{"name":"seriesRed","hex":"EF6068","reason":"y=3^x series"}],"reference":"source page 24 p24-q1-answer-graph"}
\begin{tikzpicture}[x=9mm,y=4.5mm]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{seriesBlue}{HTML}{268CFF}\definecolor{seriesRed}{HTML}{EF6068}
\path[use as bounding box] (-3.1,-3.3) rectangle (3.5,11.8);
\draw[<->,line width=0.5pt] (-2.8,0)--(2.8,0) node[right] {$x$};
\draw[<->,line width=0.5pt] (0,-3)--(0,11) node[above] {$y$};
\foreach \v in {-2,-1,1,2}{\draw[line width=0.4pt] (\v,0)--(\v,-0.35) node[below] {\special{dvisvgm:raw <g data-graph-text="tick">}$\v$\special{dvisvgm:raw </g>}};}
\foreach \v in {1,2,3,4,5,6,7,8,9}{\draw[line width=0.4pt] (-0.12,\v)--(0,\v);}
\node[left] at (-0.12,9) {\special{dvisvgm:raw <g data-graph-text="tick">}$9$\special{dvisvgm:raw </g>}};
\draw[seriesBlue,<->,line width=0.8pt,domain=-2.7:2.7,samples=100] plot (\x,{pow(2,\x)});
\draw[seriesRed,<->,line width=0.8pt,domain=-2.7:2.15,samples=100] plot (\x,{pow(3,\x)});
\foreach \v in {-2,-1,0,1,2}{\fill[seriesBlue] (\v,{pow(2,\v)}) circle (1pt);\fill[seriesRed] (\v,{pow(3,\v)}) circle (1pt);}
\node[seriesBlue,anchor=west] at (-2.7,10.2) {$y=2^x$};
\node[seriesRed,anchor=west] at (-2.7,8.5) {$y=3^x$};
\end{tikzpicture}
